SET PAGESIZE 500
SET LINESIZE 300
SET FEEDBACK ON
SET HEADING ON

SELECT 'TOTAL_MNU' AS K, COUNT(*) AS C FROM SCM_ADM_MNU_M UNION ALL SELECT 'TOTAL_API', COUNT(*) FROM SCM_ADM_API_M UNION ALL SELECT 'TOTAL_PROC', COUNT(*) FROM SCM_ADM_PROC_M UNION ALL SELECT 'TOTAL_SHEET', COUNT(*) FROM SCM_MST_SHEET_COLUMNS UNION ALL SELECT 'TOTAL_BTN', COUNT(*) FROM SCM_ADM_MNU_BTN_MPG_M UNION ALL SELECT 'TOTAL_GR_MNU', COUNT(*) FROM SCM_ADM_USER_GR_MNU_MPG_M UNION ALL SELECT 'TOTAL_GR_BTN', COUNT(*) FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M UNION ALL SELECT 'TOTAL_MSG', COUNT(*) FROM SCM_ADM_MSG_M;

SELECT MNU_ID, COUNT(*) AS CNT FROM SCM_ADM_MNU_M WHERE MNU_ID IN ('DMF0043','DMF0043_01','DMF0008','DMF0072','DMF0020','SYS0001','SYS0011','SYS0012','SYS0013','SYS0014','SYS0015') GROUP BY MNU_ID ORDER BY MNU_ID;

SELECT 'API_'||SUBSTR(API_ID, 1, INSTR(API_ID||'_','_')-1) AS K, COUNT(*) AS C FROM SCM_ADM_API_M WHERE REGEXP_LIKE(API_ID, '^(DMF0043|DMF0043_01|DMF0008|DMF0072|DMF0020|SYS0001|SYS0011|SYS0012|SYS0013|SYS0014|SYS0015)') GROUP BY SUBSTR(API_ID, 1, INSTR(API_ID||'_','_')-1) ORDER BY 1;

SELECT 'PROC_DMF0043', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%DMF0043%' UNION ALL SELECT 'PROC_DMF0008', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%DMF0008%' UNION ALL SELECT 'PROC_DMF0072', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%DMF0072%' UNION ALL SELECT 'PROC_DMF0020', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%DMF0020%' UNION ALL SELECT 'PROC_SYS0011', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%SYS0011%' UNION ALL SELECT 'PROC_SYS0012', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%SYS0012%' UNION ALL SELECT 'PROC_SYS0013', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%SYS0013%' UNION ALL SELECT 'PROC_SYS0014', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%SYS0014%' UNION ALL SELECT 'PROC_SYS0015', COUNT(*) FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE '%SYS0015%';

SELECT PROGRAM_ID, COUNT(*) AS CNT FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID IN ('DMF0043','DMF0043_01','DMF0008','DMF0072','DMF0020','SYS0001','SYS0011','SYS0012','SYS0013','SYS0014','SYS0015') GROUP BY PROGRAM_ID ORDER BY PROGRAM_ID;

SELECT MNU_ID, COUNT(*) AS CNT FROM SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID IN ('DMF0043','DMF0043_01','DMF0008','DMF0072','DMF0020','SYS0001','SYS0011','SYS0012','SYS0013','SYS0014','SYS0015') GROUP BY MNU_ID ORDER BY MNU_ID;

SELECT 'MSG_'||SUBSTR(MSG_ID, 9, 7) AS K, COUNT(*) AS C FROM SCM_ADM_MSG_M WHERE MSG_ID LIKE 'MSG_API_DMF0043%' OR MSG_ID LIKE 'MSG_API_DMF0008%' OR MSG_ID LIKE 'MSG_API_DMF0072%' OR MSG_ID LIKE 'MSG_API_DMF0020%' OR MSG_ID LIKE 'MSG_API_SYS%' OR MSG_ID LIKE '%DMF0043%' OR MSG_ID LIKE '%DMF0008%' GROUP BY SUBSTR(MSG_ID, 9, 7) ORDER BY 1;

SELECT MNU_ID, COUNT(*) AS CNT FROM SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID IN ('DMF0043','DMF0043_01','DMF0008','DMF0072','DMF0020','SYS0001','SYS0011','SYS0012','SYS0013','SYS0014','SYS0015') GROUP BY MNU_ID ORDER BY MNU_ID;

EXIT;
